window.RTLBenchLSData.register("assets/d34c3a77989d5cdfa50568abb8bc6016914eb573a4464d1e40f2531674e5abf9.txt","module origen_093168 #(parameter STRLEN=0, parameter PS2FIFO=0)\n(\n\tinput [(8*STRLEN)-1:0] conf_str,\n\tinput                   clk_sys,\n\tinput                   SPI_CLK,\n\tinput                   SPI_SS_IO,\n\tinput                   SPI_MOSI,\n\toutput                  SPI_MISO,\n\toutput reg [5:0]        JOY0,\n\toutput reg [5:0]        JOY1,\n\toutput reg [1:0]        BUTTONS,\n\toutput reg [1:0]        SWITCHES,\n\toutput                  ps2_clk,\n\toutput reg              ps2_data\n);\n\nlocalparam CORE_TYPE = 8'ha4;\n\nreg [7:0] sbuf;\nreg [2:0] cnt;\nreg [2:0] cmd;\n\nalways @(posedge SPI_CLK or posedge SPI_SS_IO) begin\n\tif(SPI_SS_IO) begin\n\t\tcnt <= 0;\n\t\tcmd <= 0;\n\tend else begin\n\t\tsbuf <= {sbuf[6:0], SPI_MOSI};\n\t\tcnt <= cnt + 1'd1;\n\t\tif(cnt == 7) begin\n\t\t\tcmd <= sbuf[2:0];\n\t\t\tif(sbuf[6:3] != 0) cmd <= 0;\n\t\tend\n\tend\nend\n\nassign SPI_MISO = (cmd == 0) ? CORE_TYPE[~cnt[2:0]] : 1'b0;\n\nalways @(posedge clk_sys) begin\n\tif(cmd == 1 && cnt == 15) begin\n\t\tBUTTONS <= {sbuf[1:0]};\n\t\tSWITCHES <= {sbuf[3:2]};\n\tend\n\tif(cmd == 2 && cnt == 15) JOY0 <= {sbuf[5:0]};\n\tif(cmd == 3 && cnt == 15) JOY1 <= {sbuf[5:0]};\nend\n\n// PS/2 keyboard\nreg [7:0] ps2_fifo [2:0];\nreg [1:0] ps2_wptr;\nreg [1:0] ps2_rptr;\nwire ps2_fifo_empty = (ps2_wptr == ps2_rptr);\n\nalways @(posedge clk_sys) begin\n\tif(cmd == 5 && cnt == 15) begin\n\t\tps2_fifo[ps2_wptr] <= sbuf;\n\t\tps2_wptr <= ps2_wptr + 1'd1;\n\tend\nend\n\nreg [3:0] ps2_tx_state;\nreg [7:0] ps2_tx_byte;\nreg ps2_parity;\n\nassign ps2_clk = (ps2_tx_state == 0);\n\nalways @(posedge clk_sys) begin\n\treg [15:0] ps2_tx_timeout;\n\n\tif(ps2_tx_timeout) ps2_tx_timeout <= ps2_tx_timeout - 1'd1;\n\n\tif(ps2_tx_timeout == 1) begin\n\t\tps2_tx_state <= 0;\n\t\tps2_data <= 1;\n\tend else begin\n\t\tcase(ps2_tx_state)\n\t\t\t0: if(!ps2_fifo_empty) begin\n\t\t\t\tps2_tx_byte <= ps2_fifo[ps2_rptr];\n\t\t\t\tps2_rptr <= ps2_rptr + 1'd1;\n\t\t\t\tps2_parity <= 1;\n\t\t\t\tps2_tx_state <= 1;\n\t\t\t\tps2_tx_timeout <= 16'd4000;\n\t\t\t\tps2_data <= 0;\n\t\t\tend\n\t\t\t1: begin\n\t\t\t\tps2_data <= ps2_tx_byte[0];\n\t\t\t\tps2_tx_byte <= {1'b0, ps2_tx_byte[7:1]};\n\t\t\t\tps2_parity <= ps2_parity ^ ps2_tx_byte[0];\n\t\t\t\tps2_tx_state <= ps2_tx_state + 1'd1;\n\t\t\tend\n\t\t\t9: begin\n\t\t\t\tps2_data <= ps2_parity;\n\t\t\t\tps2_tx_state <= ps2_tx_state + 1'd1;\n\t\t\tend\n\t\t\t10: begin\n\t\t\t\tps2_data <= 1;\n\t\t\t\tps2_tx_state <= ps2_tx_state + 1'd1;\n\t\t\tend\n\t\t\t11: ps2_tx_state <= 0;\n\t\tendcase\n\tend\nend\n\nendmodule");
